package calc

func inversions(xs []int64) int64 {
	var count int64
	for i, x := range xs {
		for j := i + 1; j < len(xs); j++ {
			if xs[j] < x {
				cnt++
			}
		}
	}
	return count
}

package calc

import "testing"

func TestInversions(t *testing.T) {
	if got := inversions([]int64{3, 1, 2}); got != 2 {
		t.Errorf("inversions([]int64{3, 1, 2}) = %d, want 2", got)
	}
	if got := inversions([]int64{2, 2, 1}); got != 2 {
		t.Errorf("inversions([]int64{2, 2, 1}) = %d, want 2", got)
	}
	if got := inversions([]int64{5, 4, 3, 2, 1}); got != 10 {
		t.Errorf("inversions([]int64{5, 4, 3, 2, 1}) = %d, want 10", got)
	}
	if got := inversions(nil); got != 0 {
		t.Errorf("inversions(nil) = %d, want 0", got)
	}
}
